// ---------------------------------------------------------------------
// Search (the contracts module's pages): every filter is a
// clause over indexed columns; the sort is chosen by a key the
// handler validates, never by raw input. Empty text means the
// filter is off; array filters are off when empty; numeric
// bands are off below zero.
// ---------------------------------------------------------------------
func (q *Queries) SearchPublicContracts(ctx context.Context, arg SearchPublicContractsParams) ([]SearchPublicContractsRow, error) {
	rows, err := q.db.QueryContext(ctx, searchPublicContracts,
		pq.Array(arg.Types),
		pq.Array(arg.RegionIds),
		arg.TitleQ,
		arg.ItemQ,
		arg.ItemDir,
		arg.ItemType,
		arg.IssuerQ,
		arg.ForCorp,
		arg.PriceMin,
		arg.PriceMax,
		arg.BuyoutMax,
		arg.PlaceQ,
		arg.PlaceEndQ,
		arg.RewardMin,
		arg.RewardMax,
		arg.CollateralMax,
		arg.VolumeMin,
		arg.VolumeMax,
		arg.DaysMax,
		arg.CourierActive,
		arg.BpActive,
		arg.BpMode,
		arg.MeMin,
		arg.TeMin,
		arg.RunsMin,
		arg.IssuedAfter,
		arg.ExpiringBefore,
		arg.AbyssalActive,
		arg.AbFamily,
		arg.AbScoreMin,
		arg.AbSourceQ,
		arg.AbEstMin,
		arg.AbEstMax,
		arg.AbAttrKey,
		arg.AbAttrMin,
		arg.AbRollBands,
		arg.AbPosMin,
		arg.DealsOnly,
		arg.ExcludeUndockable,
		arg.ExcludeMulti,
		arg.SecMin,
		arg.Sort,
		arg.RowOffset,
		arg.MaxRows,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []SearchPublicContractsRow
	for rows.Next() {
		var i SearchPublicContractsRow
		if err := rows.Scan(
			&i.ContractID,
			&i.RegionID,
			&i.Type,
			&i.IssuerID,
			&i.IssuerCorporationID,
			&i.ForCorporation,
			&i.Title,
			&i.Price,
			&i.Buyout,
			&i.Reward,
			&i.Collateral,
			&i.Volume,
			&i.StartLocationID,
			&i.EndLocationID,
			&i.DateIssued,
			&i.DateExpired,
			&i.DaysToComplete,
			&i.ItemsState,
			&i.LastCycle,
			&i.FirstSeen,
			&i.LastSeen,
			&i.OfferedValue,
			&i.WantValue,
			&i.DealRatio,
			&i.PricedLines,
			&i.TotalLines,
			&i.TierMix,
			&i.PricedAt,
			&i.TopBid,
			&i.BidCount,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

