const upsertAbyssalItem = `-- name: UpsertAbyssalItem :exec
INSERT INTO abyssal_items (
    item_id, type_id, source_type_id, mutator_type_id, created_by,
    attributes, fetched_at, first_seen_at, last_seen_at)
VALUES ($1, $2, $3, $4, $5, $6, $7, $8, $8)
ON CONFLICT (item_id) DO UPDATE SET
    last_seen_at = excluded.last_seen_at
`

type UpsertAbyssalItemParams struct {
	ItemID        int64           `json:"item_id"`
	TypeID        int64           `json:"type_id"`
	SourceTypeID  int64           `json:"source_type_id"`
	MutatorTypeID int64           `json:"mutator_type_id"`
	CreatedBy     int64           `json:"created_by"`
	Attributes    json.RawMessage `json:"attributes"`
	FetchedAt     time.Time       `json:"fetched_at"`
	FirstSeenAt   time.Time       `json:"first_seen_at"`
}

// An instance's rolls never change: the first fetch is the
// row; later sightings of the same instance only move
// last_seen_at.
func (q *Queries) UpsertAbyssalItem(ctx context.Context, arg UpsertAbyssalItemParams) error {
	_, err := q.db.ExecContext(ctx, upsertAbyssalItem,
		arg.ItemID,
		arg.TypeID,
		arg.SourceTypeID,
		arg.MutatorTypeID,
		arg.CreatedBy,
		arg.Attributes,
		arg.FetchedAt,
		arg.FirstSeenAt,
	)
	return err
}

